dialog.addEventListener('close',()=>document.body.style.overflow='');
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if("'!b)return;const s=state[b.dataset.context];if(b.dataset.action==='"'member')s.member="'!s.member;if(b.dataset.action==='"'book')s.booked=true;if(b.dataset.action==='checkin')s.checked=true;const ctx=b.dataset.context;if(ctx==='inline')renderInline();else renderModal();const next=document.querySelector("'`[data-context="${ctx}"][data-action="${b.dataset.action}"]`);if(next&&!next.disabled)next.focus()});
document.querySelectorAll('"'[role=\"tablist\"]').forEach(list=>list.addEventListener('keydown',e=>{const vertical=list.getAttribute('aria-orientation')==='vertical';const prev=vertical?'ArrowUp':'ArrowLeft',next=vertical?'ArrowDown':'ArrowRight';if("'![prev,next,'"'Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...list.querySelectorAll('[role=\"tab\"]')];let i=buttons.indexOf(document.activeElement);if(i===-1)return;i=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key===next?1:-1)+buttons.length)%buttons.length;const b=buttons[i];if(b.dataset.feature)selectFeature(b.dataset.feature,true);else selectDemo(b.dataset.demoTab,true)}));
renderInline();renderModal();
})();
