<div class=\"modal-header\"><h2 id=\"demo-title\">A look inside Tidepool</h2><button class=\"close-button\" aria-label=\"Close demo\">×</button></div>
<div class=\"modal-body\"><p>Meet Boulder House, our sample gym. Try the three everyday jobs Tidepool brings together.</p><div class=\"modal-tabs\" role=\"tablist\" aria-label=\"Demo sections\"><button id=\"demo-tab-memberships\" role=\"tab\" aria-selected=\"true\" aria-controls=\"demo-panel\" data-demo-tab=\"memberships\">Memberships</button><button id=\"demo-tab-classes\" role=\"tab\" aria-selected=\"false\" aria-controls=\"demo-panel\" tabindex=\"-1\" data-demo-tab=\"classes\">Class bookings</button><button id=\"demo-tab-passes\" role=\"tab\" aria-selected=\"false\" aria-controls=\"demo-panel\" tabindex=\"-1\" data-demo-tab=\"passes\">Day passes</button></div><div id=\"demo-panel\" role=\"tabpanel\" aria-labelledby=\"demo-tab-memberships\" tabindex=\"0\"></div><p class=\"modal-bottom\">This is an interactive preview. All names and activity are sample data.</p></div>
</dialog>
<script>
(()=>{
const dialog=document.querySelector('#demo-dialog');
let feature='memberships',demoFeature='memberships';
const state={inline:{member:false,booked:false,checked:false},modal:{member:false,booked:false,checked:false}};
const labels={memberships:'Memberships',classes:'Class bookings',passes:'Day passes'};
function preview(type,context){
 const s=state[context];
 let body='';
 if(type==='memberships')body="'`<div class="preview-summary"><span class="avatar">JE</span><div><h3>Jamie Ellis</h3><p>Member at Boulder House</p></div></div><dl class="preview-details"><div><dt>Membership</dt><dd>Monthly climbing</dd></div><div><dt>Status</dt><dd><span class="tag">Active member</span></dd></div></dl><div class="preview-footer"><span>A familiar face.<br>All the right details.</span><button class="demo-button" data-action="member" data-context="${context}" aria-expanded="${s.member}">${s.member?'"'Hide details':'View membership'} <span aria-hidden=\"true\">→</span></button></div>"'${s.member?'"'<div class=\"member-info\"><strong>Jamie’s membership</strong><br>Monthly climbing · Active<br>Sample member ID: BH-0248<br>Last visit: Today</div>':''}"'`;
 if(type==='"'classes')body="'`<div class="preview-summary"><span class="avatar"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/></svg></span><div><h3>Intro to bouldering</h3><p>Sample class · Today, 6:00 pm</p></div></div><dl class="preview-details"><div><dt>Booked</dt><dd>${s.booked?'"'7':'6'} of 8 climbers</dd></div><div><dt>Availability</dt><dd><span class=\"tag\">"'${s.booked?'"'1 spot left':'2 spots left'}</span></dd></div></dl><div class=\"preview-footer\"><span>Make a little room<br>for a new climber.</span><button class=\"demo-button\" data-action=\"book\" data-context=\""'${context}" ${s.booked?'"'disabled':''}>"'${s.booked?'"'Spot reserved ✓':'Reserve sample spot →'}</button></div>"'${s.booked?'"'<p class=\"demo-feedback\" role=\"status\">Jamie is booked into Intro to bouldering.</p>':''}"'`;
 if(type==='"'passes')body="'`<div class="preview-summary"><span class="avatar">AT</span><div><h3>Alex Taylor</h3><p>Day visitor at Boulder House</p></div></div><dl class="preview-details"><div><dt>Pass type</dt><dd>Single day pass</dd></div><div><dt>Status</dt><dd><span class="tag">${s.checked?'"'Checked in':'Ready to climb'}</span></dd></div></dl><div class=\"preview-footer\"><span>One warm welcome.<br>One more climber on the wall.</span><button class=\"demo-button\" data-action=\"checkin\" data-context=\""'${context}" ${s.checked?'"'disabled':''}>"'${s.checked?'"'Checked in ✓':'Check in sample guest →'}</button></div>"'${s.checked?'"'<p class=\"demo-feedback\" role=\"status\">Alex is checked in. Have a good climb"'!</p>'"':''}"'`;
 return `<div class="preview"><div class="preview-header"><strong>${labels[type]}</strong><span class="sample-label">Sample gym</span></div><div class="preview-content">${body}</div></div>`;
}
function renderInline(){document.querySelector('"'#inline-preview').innerHTML=preview(feature,'inline')}
function renderModal(){document.querySelector('#demo-panel').innerHTML=preview(demoFeature,'modal')}
function selectFeature(value,focus=false){feature=value;document.querySelectorAll('[data-feature]').forEach(b=>{let active=b.dataset.feature===value;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;if(active&&focus)b.focus()});document.querySelector('#toolkit-panel').setAttribute('aria-labelledby','tab-'+value);renderInline()}
function selectDemo(value,focus=false){demoFeature=value;document.querySelectorAll('[data-demo-tab]').forEach(b=>{let active=b.dataset.demoTab===value;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;if(active&&focus)b.focus()});document.querySelector('#demo-panel').setAttribute('aria-labelledby','demo-tab-'+value);renderModal()}
