document.querySelectorAll('"'[role=\"tablist\"]').forEach(list=>list.addEventListener('keydown',e=>{const vertical=list.getAttribute('aria-orientation')==='vertical';const prev=vertical?'ArrowUp':'ArrowLeft',next=vertical?'ArrowDown':'ArrowRight';if("'![prev,next,'"'Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...list.querySelectorAll('[role=\"tab\"]')];let i=buttons.indexOf(document.activeElement);if(i===-1)return;i=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key===next?1:-1)+buttons.length)%buttons.length;const b=buttons[i];if(b.dataset.feature)selectFeature(b.dataset.feature,true);else selectDemo(b.dataset.demoTab,true)}));
renderInline();renderModal();
})();
